qc.x(qr_035894[1])
qc.measure(qr_035894[0], cr_035894[0]) 
qc.measure(qr_035894[1], cr_035894[1]) 
with qc.while_loop((cr_035894, 0b11)): 
	qc.measure(qr_035894[0], cr_035894[0]) 
	qc.measure(qr_035894[1], cr_035894[1]) 
	pass
	
	qc.break_loop()
qc.reset(qr_035894)
