qc.append(g_4eaf25, [3,2,1,4]) 
qc.append(U3Gate(0.964, 2.306, 4.678), [qreg[1]])
qc.append(Permutation(4, pattern=[2, 0, 1, 3]), [qreg[3], qreg[4], qreg[1], qreg[0]])
qc.ry(0.7853981633974483, 4)
qc.ccx(3, 2, 1)
qc.crx(0.7853981633974483, 4, 3)
qc.append(AND(1), [qreg[2], qreg[0]])
qc.y(1)
qc.measure(qreg[0], creg[0]) 
qc.measure(qreg[1], creg[1]) 
qc.measure(qreg[2], creg[2]) 
qc.measure(qreg[3], creg[3]) 
qc.measure(qreg[4], creg[4]) 

qc = qc.assign_parameters({p: 0.5 for p in qc.parameters})


simulator = Aer.get_backend("aer_simulator") 

p = PassManager([OptimizeSwapBeforeMeasure(),CommutativeInverseCancellation(),ResetAfterMeasureSimplification()]) 
qc = p.run(qc) 

compiled_circuit = transpile(qc, backend = simulator, optimization_level = 3, routing_method = "default", layout_method = "noise_adaptive", approximation_degree = 1) 

qc = qc.decompose(reps=10)

job = simulator.run(compiled_circuit, shots=500) 
result = job.result().get_counts() 
print(result)
